package net.j5os.chaoscontrol;
import android.app.*;
import android.content.*;
import android.media.*;
import android.media.audiofx.*;
import android.net.Uri;
import android.os.*;
import java.util.*;
import org.json.*;
public class AudioService extends Service {
 static AudioService instance; MediaPlayer player; LoudnessEnhancer loud; BassBoost bass; Equalizer eq;
 ArrayList<String> tracks=new ArrayList<>(); int index=0,gain=100,base=0; boolean repeat=false,shuffle=false,auto=false,prepared=false; String status="Hazır";
 public void onCreate(){super.onCreate();instance=this;android.content.SharedPreferences p=getSharedPreferences("chaos_audio",0);gain=p.getInt("gain",100);base=p.getInt("bass",0);repeat=p.getBoolean("repeat",false);shuffle=p.getBoolean("shuffle",false);auto=p.getBoolean("auto",false);try{JSONArray a=new JSONArray(p.getString("tracks","[]"));for(int i=0;i<a.length();i++)tracks.add(a.getString(i));}catch(Exception ignored){}}
 void save(){getSharedPreferences("chaos_audio",0).edit().putString("tracks",new JSONArray(tracks).toString()).putInt("gain",gain).putInt("bass",base).putBoolean("repeat",repeat).putBoolean("shuffle",shuffle).putBoolean("auto",auto).apply();}
 static void send(Context c,String action){c.startForegroundService(new Intent(c,AudioService.class).setAction(action));}
 public int onStartCommand(Intent i,int flags,int id){notifyPlayer();if(i==null)return START_NOT_STICKY;String a=i.getAction();if("add".equals(a)){ArrayList<String> items=i.getStringArrayListExtra("uris");if(items!=null)for(String u:items)if(!tracks.contains(u))tracks.add(u);save();}else if("play".equals(a))toggle();else if("next".equals(a))next(1);else if("prev".equals(a))next(-1);else if("stop".equals(a)){release();stopSelf();return START_NOT_STICKY;}else if("clear".equals(a)){release();tracks.clear();index=0;save();}else if("select".equals(a))play(i.getIntExtra("index",0));else if("gain".equals(a)){gain=Math.max(100,Math.min(200,i.getIntExtra("value",100)));effects();save();}else if("bass".equals(a)){base=Math.max(0,Math.min(500,i.getIntExtra("value",0)));effects();save();}else if("repeat".equals(a)){repeat=!repeat;save();}else if("shuffle".equals(a)){shuffle=!shuffle;save();}else if("auto".equals(a)){auto=!auto;effects();save();}else if("reset".equals(a)){gain=100;base=0;auto=false;effects();save();}notifyPlayer();return START_NOT_STICKY;}
 void notifyPlayer(){NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("audio","Chaos Soundboard",NotificationManager.IMPORTANCE_LOW));PendingIntent pi=PendingIntent.getActivity(this,99,new Intent(this,AudioActivity.class),PendingIntent.FLAG_IMMUTABLE);Notification.Builder n=new Notification.Builder(this,"audio").setSmallIcon(android.R.drawable.ic_media_play).setContentTitle("CHAOS SOUNDBOARD").setContentText(title()+" • "+status).setContentIntent(pi).setOnlyAlertOnce(true);String[] acts={"prev","play","next","stop"};String[] names={"Önceki","Oynat/Duraklat","Sonraki","Durdur"};for(int j=0;j<acts.length;j++){PendingIntent a=PendingIntent.getService(this,100+j,new Intent(this,AudioService.class).setAction(acts[j]),PendingIntent.FLAG_IMMUTABLE);n.addAction(new Notification.Action.Builder(null,names[j],a).build());}startForeground(99,n.build());}
 String title(){if(tracks.isEmpty())return "Playlist boş";try{Uri u=Uri.parse(tracks.get(Math.max(0,Math.min(index,tracks.size()-1))));try(android.database.Cursor c=getContentResolver().query(u,new String[]{"_display_name"},null,null,null)){if(c!=null&&c.moveToFirst())return c.getString(0);}return u.getLastPathSegment();}catch(Exception e){return "Ses dosyası";}}
 void toggle(){if(player==null){play(index);return;}if(!prepared)return;try{if(player.isPlaying()){player.pause();status="Duraklatıldı";}else{player.start();status="Oynatılıyor";}}catch(Exception e){status="Ses hatası";}}
 void next(int step){if(tracks.isEmpty())return;int n=shuffle&&step>0?new Random().nextInt(tracks.size()):(index+step+tracks.size())%tracks.size();play(n);}
 void play(int n){if(tracks.isEmpty())return;release();index=Math.max(0,Math.min(n,tracks.size()-1));try{player=new MediaPlayer();player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());player.setDataSource(this,Uri.parse(tracks.get(index)));player.setOnPreparedListener(p->{if(p!=player)return;prepared=true;try{loud=new LoudnessEnhancer(p.getAudioSessionId());}catch(Exception ignored){}try{bass=new BassBoost(0,p.getAudioSessionId());}catch(Exception ignored){}try{eq=new Equalizer(0,p.getAudioSessionId());}catch(Exception ignored){}effects();p.start();status="Oynatılıyor";notifyPlayer();});player.setOnCompletionListener(p->{if(repeat)play(index);else if(shuffle||index+1<tracks.size())next(1);else{release();status="Playlist bitti";notifyPlayer();}});player.setOnErrorListener((p,w,e)->{release();status="Dosya okunamadı";notifyPlayer();return true;});status="Hazırlanıyor";player.prepareAsync();}catch(Exception e){release();status="Dosya açılamadı";}}
 void effects(){try{if(loud!=null){loud.setTargetGain((int)(2000*Math.log10(gain/100.0))+(auto?200:0));loud.setEnabled(gain>100||auto);}}catch(Exception ignored){}try{if(bass!=null){if(bass.getStrengthSupported())bass.setStrength((short)base);bass.setEnabled(base>0);}}catch(Exception ignored){}}
 void release(){prepared=false;if(loud!=null){loud.release();loud=null;}if(bass!=null){bass.release();bass=null;}if(eq!=null){eq.release();eq=null;}if(player!=null){player.release();player=null;}status="Durdu";}
 public IBinder onBind(Intent i){return null;} public void onDestroy(){release();instance=null;stopForeground(true);super.onDestroy();}
}
